import json

class Person:
    def __init__(self, name, age, skills):
        self.name = name
        self.age = age
        self.skills = skills

class PersonEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Person):
            return {'__type__': 'Person', 'name': obj.name, 'age': obj.age, 'skills': obj.skills}
        return super().default(obj)

def decode_person(dct):
    if dct.get('__type__') == 'Person':
        return Person(dct['name'], dct['age'], dct['skills'])
    return dct

p = Person('Alice', 30, ['Python', 'Java', 'SQL'])
json_str = json.dumps(p, cls=PersonEncoder, indent=2)
print("Serialized:")
print(json_str)

restored = json.loads(json_str, object_hook=decode_person)
print(f"\nRestored: {restored.name}, Age: {restored.age}")
print(f"Skills: {', '.join(restored.skills)}")
